class Part3DGlammCriterion(nn.Module):
    def __init__(self, lang_seg_criterion, lang_criterion):
        super(Part3DGlammCriterion, self).__init__()
        self.lang_seg_criterion = MODELS.build(lang_seg_criterion)
        self.lang_criterion = MODELS.build(lang_criterion)


    def __call__(self, pred, insts, language_loss=None):

        loss = self.lang_seg_criterion(pred, insts)
        if self.lang_criterion is not None and language_loss is not None:
            loss.update(self.lang_criterion(language_loss))


        return loss



